const fs = require('fs');
const zlib = require('zlib');

const file = process.argv[2];
const want = Number(process.argv[3] || 30);

const buf = fs.readFileSync(file);
const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const offs = [];
let i = 0;
while ((i = buf.indexOf(magic, i)) >= 0) { offs.push(i); i++; }

const lines = [];
for (let k = 0; k < offs.length; k++) {
  const end = k + 1 < offs.length ? offs[k + 1] : buf.length;
  try {
    const s = zlib.zstdDecompressSync(buf.subarray(offs[k], end)).toString('utf8');
    s.split('\n').filter((l) => l.trim()).forEach((l) => lines.push(l));
  } catch {}
}

const one = (s) => String(s).replace(/\s+/g, ' ').slice(0, 260);
const events = [];
for (const l of lines) {
  let o;
  try { o = JSON.parse(l); } catch { continue; }
  const t = o.type;
  let brief = '';
  if (t === 'user/message') {
    const c = o.data && o.data.content;
    brief = Array.isArray(c) ? c.map((b) => b.text || ('[' + b.type + ']')).join(' ') : String(c);
  } else if (t === 'assistant/message') {
    const c = o.data && o.data.content;
    brief = Array.isArray(c) ? c.map((b) => b.text || ('[' + b.type + ']' + (b.name ? ':' + b.name : ''))).join(' ') : String(c);
  } else if (t === 'tool/call') {
    brief = (o.data && (o.data.name || o.data.tool)) + ' ' + one(JSON.stringify(o.data && (o.data.args || o.data.input) || ''));
  } else if (t === 'tool/result') {
    brief = one(JSON.stringify(o.data && (o.data.result || o.data) || ''));
  } else if (t === 'turn/end' || t === 'assistant/attempt') {
    brief = one(JSON.stringify(o.data));
  } else if (t === 'session/title') {
    brief = one(JSON.stringify(o.data));
  } else {
    continue;
  }
  events.push(t + ' | ' + brief);
}
events.slice(-want).forEach((e) => console.log(e + '\n'));
"}

