const fs = require('fs');
const zlib = require('zlib');

const file = process.argv[2];
const needle = process.argv[3];
const before = Number(process.argv[4] || 200);
const after = Number(process.argv[5] || 1200);
const maxHits = Number(process.argv[6] || 3);

const buf = fs.readFileSync(file);
const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const offs = [];
let i = 0;
while ((i = buf.indexOf(magic, i)) >= 0) { offs.push(i); i++; }

let text = '';
for (let k = 0; k < offs.length; k++) {
  const end = k + 1 < offs.length ? offs[k + 1] : buf.length;
  try { text += zlib.zstdDecompressSync(buf.subarray(offs[k], end)).toString('utf8'); } catch {}
}

let idx = 0, hits = 0;
while ((idx = text.indexOf(needle, idx)) >= 0 && hits < maxHits) {
  hits++;
  console.log('--- hit ' + hits + ' @' + idx + ' ---');
  console.log(text.slice(Math.max(0, idx - before), idx + after).replace(/\\n/g, '\n'));
  idx += needle.length;
}
if (hits === 0) console.log('(no match)');
